@code {
    private string trackingNumber = string.Empty;
    private Shipment? trackedShipment;
    private string? errorMessage;
    private bool isLoading;

    private async Task TrackShipment()
    {
        errorMessage = null;
        trackedShipment = null;

        if (string.IsNullOrWhiteSpace(trackingNumber))
        {
            errorMessage = "Please enter a tracking number.";
            return;
        }

        isLoading = true;
        try
        {
            trackedShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
            if (trackedShipment is null)
                errorMessage = $"No shipment found for tracking number \"{trackingNumber.Trim()}\".";
        }
        catch
        {
            errorMessage = "An error occurred while looking up your shipment. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-primary",
        _ => "bg-warning text-dark"
    };
}
