@code {
    private List<Shipment>? shipments;
    private string destinationFilter = string.Empty;
    private string statusFilter = string.Empty;
    private int? updatingId;

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private IEnumerable<Shipment> FilteredShipments =>
        (shipments ?? []).Where(s =>
            (string.IsNullOrEmpty(destinationFilter) ||
             s.Destination.Contains(destinationFilter, StringComparison.OrdinalIgnoreCase)) &&
            (string.IsNullOrEmpty(statusFilter) ||
             s.Status.ToString() == statusFilter));

    private void ClearFilters()
    {
        destinationFilter = string.Empty;
        statusFilter = string.Empty;
    }

    private async Task UpdateStatus(int id, ShipmentStatus newStatus)
    {
        updatingId = id;
        try
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
            var index = shipments!.FindIndex(s => s.Id == id);
            if (index >= 0)
                shipments[index] = updated;
        }
        finally
        {
            updatingId = null;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-primary",
        _ => "bg-warning text-dark"
    };
}
