<PageTitle>Dispatcher Dashboard</PageTitle>

<h1 class="mb-4">Dispatcher Dashboard</h1>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Filter by destination..."
               @bind="destinationFilter" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear Filters</button>
    </div>
</div>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <div class="alert alert-info">No shipments match the current filters.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Weight (kg)</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in FilteredShipments)
                {
                    <tr>
                        <td><strong>@shipment.TrackingNumber</strong></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td>@shipment.RecipientName</td>
                        <td>
                            <span class="badge @GetStatusBadgeClass(shipment.Status)">
                                @shipment.Status
                            </span>
                        </td>
                        <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>@shipment.WeightKg.ToString("F1")</td>
                        <td>
                            @if (shipment.Status != ShipmentStatus.Delivered && shipment.Status != ShipmentStatus.Returned)
                            {
                                <div class="dropdown">
                                    <button class="btn btn-sm btn-outline-primary dropdown-toggle"
                                            type="button" data-bs-toggle="dropdown"
                                            disabled="@(updatingId == shipment.Id)">
                                        @if (updatingId == shipment.Id)
                                        {
                                            <span class="spinner-border spinner-border-sm" role="status"></span>
                                        }
                                        else
                                        {
                                            <span>Update</span>
                                        }
                                    </button>
                                    <ul class="dropdown-menu">
                                        @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                        {
                                            if (status != shipment.Status)
                                            {
                                                var s = status;
                                                <li>
                                                    <button class="dropdown-item" @onclick="() => UpdateStatus(shipment.Id, s)">
                                                        @s
                                                    </button>
                                                </li>
                                            }
                                        }
                                    </ul>
                                </div>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@code {
    private List<Shipment>? shipments;
    private string destinationFilter = string.Empty;
    private string statusFilter = string.Empty;
    private int? updatingId;

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private IEnumerable<Shipment> FilteredShipments =>
        (shipments ?? []).Where(s =>
            (string.IsNullOrEmpty(destinationFilter) ||
             s.Destination.Contains(destinationFilter, StringComparison.OrdinalIgnoreCase)) &&
            (string.IsNullOrEmpty(statusFilter) ||
             s.Status.ToString() == statusFilter));

    private void ClearFilters()
    {
        destinationFilter = string.Empty;
        statusFilter = string.Empty;
    }

    private async Task UpdateStatus(int id, ShipmentStatus newStatus)
    {
        updatingId = id;
        try
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
            var index = shipments!.FindIndex(s => s.Id == id);
            if (index >= 0)
                shipments[index] = updated;
        }
        finally
        {
            updatingId = null;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-primary",
        _ => "bg-warning text-dark"
    };
}

