<PageTitle>Track Your Shipment</PageTitle>

<div class="container">
    <h1 class="mb-4">📦 Shipment Tracker</h1>
    <p class="lead">Enter your tracking number to check your shipment status and estimated delivery.</p>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="e.g. TRK-1001"
                       @bind="trackingNumber" @bind:event="oninput"
                       @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                    @if (isLoading)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Track
                </button>
            </div>
        </div>
    </div>

    @if (errorMessage is not null)
    {
        <div class="alert alert-warning" role="alert">
            @errorMessage
        </div>
    }

    @if (trackedShipment is not null)
    {
        <div class="card">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h5 class="mb-0">Tracking: @trackedShipment.TrackingNumber</h5>
                <span class="badge @GetStatusBadgeClass(trackedShipment.Status) fs-6">
                    @trackedShipment.Status
                </span>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <p><strong>From:</strong> @trackedShipment.Origin</p>
                        <p><strong>To:</strong> @trackedShipment.Destination</p>
                        <p><strong>Sender:</strong> @trackedShipment.SenderName</p>
                        <p><strong>Recipient:</strong> @trackedShipment.RecipientName</p>
                    </div>
                    <div class="col-md-6">
                        <p><strong>Shipped:</strong> @trackedShipment.ShippedDate.ToString("MMM dd, yyyy")</p>
                        <p><strong>Estimated Delivery:</strong> @trackedShipment.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
                        @if (trackedShipment.ActualDelivery.HasValue)
